#include <WiFi.h>
#include <WiFiClientSecure.h>

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  WiFiClientSecure c;
  c.setInsecure();
  if (!c.connect("{{host}}", 443)) { Serial.println("fail"); return; }
  c.printf("GET %s HTTP/1.0\r\nHost: %s\r\n\r\n", "{{path}}", "{{host}}");
  while (c.connected() || c.available()) if (c.available()) Serial.write(c.read());
}

void loop() {}
